package com.wiktor.jogger;

import android.content.Context;
import android.graphics.*;
import android.os.SystemClock;
import android.view.*;
import java.io.*;
import java.util.*;

/** Original multi-pointer mobile HUD. Draws installed Minecraft widget textures. */
public final class TouchOverlay extends View {
 public interface Actions {void type();void leaveChat();void exit();}
 private final Actions actions;private final Paint paint=new Paint();private final float density;
 private final List<Button> buttons=new ArrayList<>();private final Map<Integer,Pointer> pointers=new HashMap<>();private final Map<Integer,Integer> held=new HashMap<>();
 private final TouchGesture gesture;private Bitmap normal,pressed;private int worldPointer=-1;private boolean guiPointer,crouch;private long lastForward=-1000;
 private int[] status={0,3,640,360,0,1280,720,7000,500};private int previousScreen=-1;private int previousGrab=-1;private float cell,dx,dy;private boolean testing;private String lastEvent="Touch a control";
 private static final class Button {final String id,icon;final RectF r;final int key;Button(String id,String icon,RectF r,int key){this.id=id;this.icon=icon;this.r=r;this.key=key;}}
 private static final class Pointer {String button;int[]keys=new int[0];boolean moved;float x,y;Pointer(String b,float x,float y){button=b;this.x=x;this.y=y;}}
 public TouchOverlay(Context c,File dir,Actions actions,boolean test){super(c);this.actions=actions;testing=test;density=getResources().getDisplayMetrics().density;setFocusable(false);setContentDescription("Classic mobile controls");loadTextures(dir);gesture=new TouchGesture(9*density,new TouchGesture.Sink(){public void look(float x,float y){lastEvent="Look "+Math.round(x)+", "+Math.round(y);if(!testing){double scale=Math.max(.15,getContext().getSharedPreferences("jogger",0).getInt("lookSpeed",100)/100.0);Native.input(2,1,0,x*status[5]/Math.max(1,getWidth())*scale,y*status[6]/Math.max(1,getHeight())*scale);}}public void mine(boolean down,float x,float y){lastEvent=down?"Mining touched block":"Mining released";if(!testing){if(down)Native.target(x/getWidth(),y/getHeight(),0,true);else Native.cancelTarget();}}public void place(float x,float y){lastEvent="Use at "+Math.round(x)+", "+Math.round(y);if(!testing)Native.target(x/getWidth(),y/getHeight(),1,false);}});}
 private void loadTextures(File d){if(d==null)return;normal=BitmapFactory.decodeFile(new File(d,"jogger-ui/button.png").toString());pressed=BitmapFactory.decodeFile(new File(d,"jogger-ui/button_highlighted.png").toString());if(normal==null){Bitmap atlas=BitmapFactory.decodeFile(new File(d,"jogger-ui/widgets.png").toString());if(atlas!=null&&atlas.getWidth()>=200&&atlas.getHeight()>=106){normal=Bitmap.createBitmap(atlas,0,66,200,20);pressed=Bitmap.createBitmap(atlas,0,86,200,20);}}}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();post(poll);}
 @Override protected void onDetachedFromWindow(){removeCallbacks(poll);reset();super.onDetachedFromWindow();}
 private final Runnable poll=new Runnable(){public void run(){if(!testing)status=Native.state();else status=new int[]{1,0,Math.max(320,(int)(getWidth()/(density*1.4f))),Math.max(180,(int)(getHeight()/(density*1.4f))),1,1280,720,7000,500};if(status[1]!=previousScreen||status[0]!=previousGrab){reset();previousScreen=status[1];previousGrab=status[0];layoutButtons();invalidate();}gesture.tick(SystemClock.uptimeMillis());if(testing)invalidate();postDelayed(this,50);}};
 @Override protected void onSizeChanged(int w,int h,int ow,int oh){super.onSizeChanged(w,h,ow,oh);reset();layoutButtons();}
 private float dp(float x){return x*density;}
 private void add(String id,String icon,float x,float y,float w,float h,int key){buttons.add(new Button(id,icon,new RectF(x,y,x+w,y+h),key));}
 private void layoutButtons(){buttons.clear();float w=getWidth(),h=getHeight(),fit=Math.min(1,h/dp(340));cell=dp(45)*fit;dx=dp(16);dy=h-dp(20)-cell*3;float top=dp(8),bw=dp(46),bh=dp(36),gap=dp(5);boolean ingame=status[0]==1&&status[1]==0;boolean chat=status[1]==1;
  if(ingame){add("chat","chat",w/2-bw-gap/2,top,bw,bh,84);add("pause","pause",w/2+gap/2,top,bw,bh,256);add("exit","exit",w-dp(54),top,bw,bh,0);
   add("jump","jump",w-dp(22)-cell*1.25f,h-dp(36)-cell*1.25f,cell*1.25f,cell*1.25f,32);
   add("mine","mine",w-dp(35)-cell*2.3f,h-dp(40)-cell*1.5f,cell,cell,-1);
   add("use","use",w-dp(22)-cell,h-dp(52)-cell*2.55f,cell,cell,-2);
   float gs=w/Math.max(1,status[2]),slot=20*gs,hotbarLeft=w/2-90*gs;float iy=h-slot;
   add("inventory","dots",Math.min(w-slot-dp(3),hotbarLeft+180*gs+gs),iy,slot,slot,69);
   for(int i=0;i<9;i++)add("slot"+i,"",hotbarLeft+i*slot,iy,slot,slot,49+i);
  }else{add(chat?"leavechat":"back","back",dp(10),top,chat?dp(70):bw,bh,256);add("type","keyboard",w/2-bw/2,top,bw,bh,0);if(chat)add("send","send",w-dp(58),top,bw,bh,257);else add("exit","exit",w-dp(58),top,bw,bh,0);}
 }
 private boolean inPad(float x,float y){return status[0]==1&&status[1]==0&&x>=dx&&x<dx+3*cell&&y>=dy&&y<dy+3*cell;}
 private int[] padKeys(float x,float y){int c=(int)((x-dx)/cell),r=(int)((y-dy)/cell);if(c<0||c>2||r<0||r>2)return new int[0];if(c==1&&r==1)return new int[]{340};if(r==0){if(c==0)return new int[]{87,65};if(c==2)return new int[]{87,68};return new int[]{87};}if(r==2)return c==1?new int[]{83}:new int[0];return c==0?new int[]{65}:new int[]{68};}
 private Button hit(float x,float y){for(Button b:buttons)if(b.r.contains(x,y))return b;return null;}
 private void key(int k,boolean down){int n=held.getOrDefault(k,0);if(down){held.put(k,n+1);if(n==0&&!testing)Native.key(k,true);}else if(n>0){if(n==1){held.remove(k);if(!testing)Native.key(k,false);}else held.put(k,n-1);}lastEvent="Key "+k+(down?" down":" up");}
 private void change(Pointer p,int[] newKeys){for(int old:p.keys){boolean remains=false;for(int k:newKeys)if(k==old)remains=true;if(!remains)key(old,false);}for(int k:newKeys){boolean had=false;for(int old:p.keys)if(old==k)had=true;if(!had)key(k,true);}p.keys=newKeys;}
 private boolean has(int[]a,int n){for(int v:a)if(v==n)return true;return false;}
 private int[] sprintKeys(int[]a){if(has(a,87)&&held.containsKey(341)){int[] b=Arrays.copyOf(a,a.length+1);b[a.length]=341;return b;}return a;}
 private void down(int id,float x,float y,long time){Button b=hit(x,y);if(inPad(x,y)){Pointer p=new Pointer("pad",x,y);int[] ks=padKeys(x,y);if(ks.length==1&&ks[0]==340){p.button="crouch";}else{if(has(ks,87)){if(time-lastForward<=280){int[] more=Arrays.copyOf(ks,ks.length+1);more[ks.length]=341;ks=more;}lastForward=time;}change(p,ks);}pointers.put(id,p);}
  else if(b!=null){Pointer p=new Pointer(b.id,x,y);pointers.put(id,p);if(b.key>0&&!b.id.equals("chat")&&!b.id.equals("leavechat")&&!b.id.equals("back")&&!b.id.equals("send")&&!b.id.equals("pause")&&!b.id.equals("inventory")&&!b.id.startsWith("slot")){change(p,new int[]{b.key});}else if(b.id.equals("mine")||b.id.equals("use")){if(!testing)Native.mouse(b.id.equals("mine")?0:1,true);} }
  else if(worldPointer<0){worldPointer=id;guiPointer=status[0]!=1||status[1]!=0;if(guiPointer){if(!testing){Native.input(2,0,0,x*status[5]/Math.max(1,getWidth()),y*status[6]/Math.max(1,getHeight()));Native.mouse(0,true);}}else gesture.down(x,y,time);}
 }
 private void move(int id,float x,float y,long time){Pointer p=pointers.get(id);if(p!=null){if(Math.hypot(x-p.x,y-p.y)>dp(8))p.moved=true;if(p.button.equals("pad")){int[] ks=padKeys(x,y);if(has(p.keys,341)&&has(ks,87)){int[] a=Arrays.copyOf(ks,ks.length+1);a[ks.length]=341;ks=a;}if(has(ks,340))ks=new int[0];change(p,ks);}return;}if(worldPointer!=id)return;if(guiPointer){if(!testing)Native.input(2,0,0,x*status[5]/Math.max(1,getWidth()),y*status[6]/Math.max(1,getHeight()));}else gesture.move(x,y,time);}
 private void up(int id,float x,float y,long time,boolean cancelled){Pointer p=pointers.remove(id);if(p!=null){change(p,new int[0]);if(p.button.equals("mine")||p.button.equals("use")){if(!testing)Native.mouse(p.button.equals("mine")?0:1,false);}else if(!cancelled){Button b=hit(x,y);if(p.button.equals("crouch")&&!p.moved){crouch=!crouch;key(340,crouch);}else if(b!=null&&b.id.equals(p.button)&&!p.moved){lastEvent=b.id;if(!testing){if(b.id.equals("exit"))actions.exit();else if(b.id.equals("type"))actions.type();else if(b.id.equals("leavechat")){Native.press(256);actions.leaveChat();}else if(b.id.equals("send")){Native.press(257);actions.leaveChat();}else if(b.id.equals("chat")){Native.press(84);postDelayed(actions::type,180);}else if(b.key>0)Native.press(b.key);}}}return;}
  if(worldPointer==id){worldPointer=-1;if(guiPointer){if(!testing)Native.mouse(0,false);}else if(cancelled)gesture.cancel();else gesture.up(x,y,time);}
 }
 @Override public boolean onTouchEvent(MotionEvent e){long t=e.getEventTime();int a=e.getActionMasked(),i=e.getActionIndex();if(a==MotionEvent.ACTION_DOWN||a==MotionEvent.ACTION_POINTER_DOWN)down(e.getPointerId(i),e.getX(i),e.getY(i),t);else if(a==MotionEvent.ACTION_MOVE){for(int n=0;n<e.getPointerCount();n++)move(e.getPointerId(n),e.getX(n),e.getY(n),t);}else if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_POINTER_UP)up(e.getPointerId(i),e.getX(i),e.getY(i),t,false);else if(a==MotionEvent.ACTION_CANCEL)reset();invalidate();return true;}
 public void reset(){if(gesture!=null)gesture.cancel();pointers.clear();held.clear();worldPointer=-1;crouch=false;if(!testing)Native.release();invalidate();}
 private void texture(Canvas c,RectF r,boolean down){Bitmap b=down&&pressed!=null?pressed:normal;paint.setAntiAlias(false);paint.setFilterBitmap(false);paint.setAlpha(210);if(b!=null){int cap=Math.min(3,b.getWidth()/4);float edge=Math.min(r.height()/4,dp(4));c.drawBitmap(b,new Rect(0,0,cap,b.getHeight()),new RectF(r.left,r.top,r.left+edge,r.bottom),paint);c.drawBitmap(b,new Rect(cap,0,b.getWidth()-cap,b.getHeight()),new RectF(r.left+edge,r.top,r.right-edge,r.bottom),paint);c.drawBitmap(b,new Rect(b.getWidth()-cap,0,b.getWidth(),b.getHeight()),new RectF(r.right-edge,r.top,r.right,r.bottom),paint);}else{paint.setColor(down?0xff4c4c4c:0xff777777);c.drawRect(r,paint);paint.setColor(0xffbbbbbb);c.drawRect(r.left+1,r.top+1,r.right-1,r.top+dp(2),paint);c.drawRect(r.left+1,r.top+1,r.left+dp(2),r.bottom-1,paint);paint.setColor(0xff292929);c.drawRect(r.left,r.bottom-dp(2),r.right,r.bottom,paint);c.drawRect(r.right-dp(2),r.top,r.right,r.bottom,paint);}paint.setAlpha(255);}
 private void icon(Canvas c,RectF r,String name){float x=r.centerX(),y=r.centerY(),s=Math.min(r.width(),r.height())*.24f;paint.setColor(0xffeeeeee);paint.setStrokeWidth(Math.max(2,dp(2)));paint.setStyle(Paint.Style.FILL);if(name.equals("dots")){for(int i=-1;i<=1;i++)c.drawRect(x+i*s*.9f-s*.18f,y-s*.18f,x+i*s*.9f+s*.18f,y+s*.18f,paint);return;}if(name.equals("pause")){c.drawRect(x-s,y-s,x-s*.25f,y+s,paint);c.drawRect(x+s*.25f,y-s,x+s,y+s,paint);return;}if(name.equals("up")||name.equals("down")||name.equals("left")||name.equals("right")||name.equals("jump")){c.save();c.rotate(name.equals("left")?-90:name.equals("right")?90:name.equals("down")?180:0,x,y);Path p=new Path();p.moveTo(x,y-s);p.lineTo(x+s,y+s*.45f);p.lineTo(x+s*.35f,y+s*.45f);p.lineTo(x+s*.35f,y+s);p.lineTo(x-s*.35f,y+s);p.lineTo(x-s*.35f,y+s*.45f);p.lineTo(x-s,y+s*.45f);p.close();c.drawPath(p,paint);c.restore();return;}if(name.equals("crouch")){c.drawRect(x-s*.25f,y-s,x+s*.3f,y-s*.4f,paint);c.drawRect(x-s*.8f,y-s*.25f,x+s*.5f,y+s*.1f,paint);c.drawRect(x+s*.15f,y,x+s*.55f,y+s*.75f,paint);c.drawRect(x-s*.65f,y+s*.65f,x+s*.55f,y+s,paint);return;}paint.setStyle(Paint.Style.STROKE);if(name.equals("chat")){c.drawRect(x-s,y-s*.7f,x+s,y+s*.55f,paint);c.drawLine(x-s*.5f,y+s*.55f,x-s*.5f,y+s,paint);c.drawLine(x-s*.5f,y+s,x,y+s*.55f,paint);}else if(name.equals("keyboard")){c.drawRect(x-s,y-s*.65f,x+s,y+s*.65f,paint);for(int row=0;row<2;row++)for(int col=0;col<3;col++)c.drawPoint(x-s*.6f+col*s*.6f,y-s*.3f+row*s*.6f,paint);}else if(name.equals("use")){c.drawRect(x-s*.7f,y-s*.7f,x+s*.7f,y+s*.7f,paint);c.drawLine(x-s*.7f,y,x+s*.7f,y,paint);}else if(name.equals("mine")){c.drawLine(x-s*.7f,y+s,x+s*.4f,y-s*.55f,paint);c.drawLine(x-s*.5f,y-s*.8f,x+s,y-s*.3f,paint);}else if(name.equals("back")){c.drawLine(x+s,y,x-s,y,paint);c.drawLine(x-s,y,x,y-s,paint);c.drawLine(x-s,y,x,y+s,paint);}else if(name.equals("send")){c.drawLine(x-s,y-s,x+s,y,paint);c.drawLine(x+s,y,x-s,y+s,paint);c.drawLine(x-s,y+s,x-s*.3f,y,paint);c.drawLine(x-s*.3f,y,x-s,y-s,paint);}else{c.drawLine(x-s,y-s,x+s,y+s,paint);c.drawLine(x+s,y-s,x-s,y+s,paint);}paint.setStyle(Paint.Style.FILL);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);if(status[0]==1&&status[1]==0){String[] names={"","up","","left","crouch","right","","down",""};int[]ks={0,87,0,65,340,68,0,83,0};for(int i=0;i<9;i++){if(names[i].isEmpty())continue;RectF r=new RectF(dx+i%3*cell+dp(1),dy+i/3*cell+dp(1),dx+(i%3+1)*cell-dp(1),dy+(i/3+1)*cell-dp(1));texture(c,r,held.containsKey(ks[i]));icon(c,r,names[i]);}}
  for(Button b:buttons){if(b.id.startsWith("slot"))continue;boolean down=held.containsKey(b.key);for(Pointer p:pointers.values())if(p.button.equals(b.id))down=true;texture(c,b.r,down);icon(c,b.r,b.icon);}
  if(testing){paint.setColor(Color.WHITE);paint.setTextSize(dp(15));paint.setTextAlign(Paint.Align.CENTER);c.drawText("Controls test - no game is running",getWidth()/2f,getHeight()*.35f,paint);c.drawText(lastEvent,getWidth()/2f,getHeight()*.45f,paint);paint.setTextAlign(Paint.Align.LEFT);}
 }
}
